// nativeSessionExport records a real sender's wire offer and the identities generated by native Codex.
type nativeSessionExport struct {
	// SourceOS identifies the actual runner that produced this migration payload.
	SourceOS string `json:"source_os"`
	// ActiveID identifies the native active conversation in the captured archive.
	ActiveID string `json:"active_id"`
	// ArchivedID identifies the native archived conversation in the captured archive.
	ArchivedID string `json:"archived_id"`
	// Offer retains the real CLI's OS, paths, protocol, encoding, sizes, and checksum without rewriting them.
	Offer map[string]any `json:"offer"`
}

// sessionCaptureListener creates a test-owned TLS endpoint pinned by the real sender before any data is sent.
func sessionCaptureListener(t *testing.T) (net.Listener, string) {
	t.Helper()
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	certificate := &x509.Certificate{
		SerialNumber: big.NewInt(1), NotBefore: time.Now().Add(-time.Hour), NotAfter: time.Now().Add(time.Hour),
		KeyUsage: x509.KeyUsageDigitalSignature, ExtKeyUsage: []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
		IPAddresses: []net.IP{net.ParseIP("127.0.0.1")},
	}
	der, err := x509.CreateCertificate(rand.Reader, certificate, certificate, &key.PublicKey, key)
	if err != nil {
		t.Fatal(err)
	}
	listener, err := tls.Listen("tcp", "127.0.0.1:0", &tls.Config{
		MinVersion: tls.VersionTLS13, Certificates: []tls.Certificate{{Certificate: [][]byte{der}, PrivateKey: key}},
	})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = listener.Close() })
	digest := sha256.Sum256(der)
	return listener, hex.EncodeToString(digest[:])
}

// captureNativeSessionArchive saves the actual CLI sender's bytes so another native runner can receive them unchanged.
func captureNativeSessionArchive(t *testing.T, binary, home, output string) map[string]any {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()
	listener, fingerprint := sessionCaptureListener(t)
	stop := context.AfterFunc(ctx, func() { _ = listener.Close() })
	defer stop()
	port := fmt.Sprint(listener.Addr().(*net.TCPAddr).Port)
	sender := exec.CommandContext(ctx, binary, "send", "127.0.0.1", "--port", port,
		"--fingerprint", fingerprint, "--project-prefix", "app-api", "--skip-process-check",
		"--sqlite-home", filepath.Join(home, ".codex", "sqlite"))
	sender.Env = isolatedCodexEnvironment(t, home)
	input, err := sender.StdinPipe()
	if err != nil {
		t.Fatal(err)
	}
	defer input.Close()
	lines, logs, err := startCaptured(sender)
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if sender.ProcessState == nil {
			_ = sender.Process.Kill()
			_ = sender.Wait()
		}
	})
	raw, err := listener.Accept()
	if err != nil {
		t.Fatal(err)
	}
	defer raw.Close()
	connection := raw.(*tls.Conn)
	if err := connection.SetDeadline(time.Now().Add(45 * time.Second)); err != nil {
		t.Fatal(err)
	}
	if err := connection.HandshakeContext(ctx); err != nil {
		t.Fatal(err)
	}
	state := connection.ConnectionState()
	code, err := state.ExportKeyingMaterial("codex-transfer-pairing-v1", nil, 6)
	if err != nil {
		t.Fatal(err)
	}
	if actual := waitForLine(t, lines, "Pairing code: "); actual != "Pairing code: "+hex.EncodeToString(code) {
		t.Fatal("native sender pairing mismatch")
	}
	if _, err := io.WriteString(input, hex.EncodeToString(code)+"\n"); err != nil {
		t.Fatal(err)
	}
	offer := readPeerMessage(t, connection, "offer")
	if offer["os"] != runtime.GOOS || offer["version"] != float64(3) || offer["mode"] != "sessions" {
		t.Fatalf("native sender did not emit its own session offer: %v", offer)
	}
	writePeerMessage(t, connection, map[string]any{"kind": "ready", "version": 3, "mode": "sessions"})
	size, ok := offer["size"].(float64)
	if !ok || size <= 0 || size > 64<<20 {
		t.Fatal("unexpected native session archive size")
	}
	archive, err := os.OpenFile(filepath.Join(output, "sessions.bin"), os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0600)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := io.CopyN(archive, connection, int64(size)); err != nil {
		_ = archive.Close()
		t.Fatal(err)
	}
	if err := archive.Close(); err != nil {
		t.Fatal(err)
	}
	writePeerMessage(t, connection, map[string]any{"kind": "complete", "version": 3})
	log := <-logs
	if err := sender.Wait(); err != nil {
		t.Fatalf("native sender failed: %v\n%s", err, log)
	}
	return offer
}

// TestRealCodexExport produces a portable CI artifact from this runner's real Codex and real migration sender.
func TestRealCodexExport(t *testing.T) {
	output := os.Getenv("CODEX_TRANSFER_EXPORT_DIR")
	if output == "" {
		t.Skip("set CODEX_TRANSFER_EXPORT_DIR to capture native cross-runner session data")
	}
	codexBinary := os.Getenv("CODEX_TRANSFER_CODEX_BINARY")
	if !filepath.IsAbs(codexBinary) || !filepath.IsAbs(output) {
		t.Fatal("native binary and export directory must be absolute")
	}
	if err := os.MkdirAll(output, 0700); err != nil {
		t.Fatal(err)
	}
	providerURL, _ := localResponsesFixture(t)
	home := prepareRealCodexHome(t, providerURL)
	process := startRealCodex(t, codexBinary, home)
	active := createRealCodexThread(t, process, home, "SOURCE_ACTIVE_CANARY")
	archived := createRealCodexThread(t, process, home, "SOURCE_ARCHIVED_CANARY")
	process.call(t, "thread/archive", map[string]any{"threadId": archived})
	process.stop(t)
	data := nativeSessionExport{
		SourceOS: runtime.GOOS, ActiveID: active, ArchivedID: archived,
		Offer: captureNativeSessionArchive(t, buildCLI(t), home, output),
	}
	metadata, err := json.MarshalIndent(data, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(output, "metadata.json"), metadata, 0600); err != nil {
		t.Fatal(err)
	}
	t.Logf("exported real %s sessions with their original sender offer and archive bytes", runtime.GOOS)
}

// TestRealCodexArchiveRoundTrip validates the unchanged-artifact transport bridge with both real CLI roles on this host.
func TestRealCodexArchiveRoundTrip(t *testing.T) {
	codexBinary := os.Getenv("CODEX_TRANSFER_CODEX_BINARY")
	if codexBinary == "" {
		t.Skip("set CODEX_TRANSFER_CODEX_BINARY to verify native captured-archive migration")
	}
	if !filepath.IsAbs(codexBinary) {
		t.Fatal("native binary must be absolute")
	}
	providerURL, requests := localResponsesFixture(t)
	source, destination := prepareRealCodexHome(t, providerURL), prepareRealCodexHome(t, providerURL)
	process := startRealCodex(t, codexBinary, source)
	active := createRealCodexThread(t, process, source, "SOURCE_ACTIVE_CANARY")
	archived := createRealCodexThread(t, process, source, "SOURCE_ARCHIVED_CANARY")
	process.call(t, "thread/archive", map[string]any{"threadId": archived})
	process.stop(t)
	binary, output := buildCLI(t), t.TempDir()
	offer := captureNativeSessionArchive(t, binary, source, output)
	local := prepareRealCodexReceiver(t, codexBinary, destination)
	receiveNativeSessionArchive(t, binary, destination, filepath.Join(output, "sessions.bin"), offer)
	verifyRealCodexImports(t, codexBinary, destination, active, archived, local, requests)
}

// receiveNativeSessionArchive replays one real source runner's captured wire payload into the target runner's real CLI.
func receiveNativeSessionArchive(t *testing.T, binary, home, archivePath string, offer map[string]any) {
	t.Helper()
	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()
	receiver := exec.CommandContext(
		ctx,
		binary,
		"receive",
		"--skip-process-check",
		"--sqlite-home",
		filepath.Join(home, ".codex", "sqlite"),
	)
	receiver.Env = isolatedCodexEnvironment(t, home)
	peer := startReceiverPeer(t, receiver)
	connection := peer.connection
	writePeerMessage(t, connection, offer)
	readPeerMessage(t, connection, "ready")
	archive, err := os.Open(archivePath)
	if err != nil {
		t.Fatal(err)
	}
	defer archive.Close()
	if _, err := io.Copy(connection, archive); err != nil {
		t.Fatal(err)
	}
	readPeerMessage(t, connection, "complete")
	peer.wait(t)
}

// TestRealCodexCrossPlatformImport receives actual artifacts from the other operating systems and resumes their histories.
func TestRealCodexCrossPlatformImport(t *testing.T) {
	root := os.Getenv("CODEX_TRANSFER_IMPORT_DIR")
	if root == "" {
		t.Skip("set CODEX_TRANSFER_IMPORT_DIR to downloaded native runner artifacts")
	}
	codexBinary := os.Getenv("CODEX_TRANSFER_CODEX_BINARY")
	if !filepath.IsAbs(codexBinary) || !filepath.IsAbs(root) {
		t.Fatal("native binary and import directory must be absolute")
	}
	binary := buildCLI(t)
	for _, sourceOS := range []string{"darwin", "linux", "windows"} {
		if sourceOS == runtime.GOOS {
			continue
		}
		t.Run(sourceOS+"_to_"+runtime.GOOS, func(t *testing.T) {
			directory := filepath.Join(root, "real-codex-"+sourceOS)
			metadata, err := os.ReadFile(filepath.Join(directory, "metadata.json"))
			if err != nil {
				t.Fatal(err)
			}
			var exported nativeSessionExport
			if err := json.Unmarshal(metadata, &exported); err != nil {
				t.Fatal(err)
			}
			if exported.SourceOS != sourceOS || exported.Offer["os"] != sourceOS || exported.ActiveID == "" ||
				exported.ArchivedID == "" {
				t.Fatal("native source provenance or conversation identities do not match the artifact")
			}
			providerURL, requests := localResponsesFixture(t)
			home := prepareRealCodexHome(t, providerURL)
			local := prepareRealCodexReceiver(t, codexBinary, home)
			receiveNativeSessionArchive(t, binary, home, filepath.Join(directory, "sessions.bin"), exported.Offer)
			verifyRealCodexImports(t, codexBinary, home, exported.ActiveID, exported.ArchivedID, local, requests)
			t.Logf("real %s sender data resumed successfully on real %s Codex", sourceOS, runtime.GOOS)
		})
	}
}
